python3 - <<'PYEOF'
import json
S='/private/tmp/opensip-design-corrections/claude-root-binding-correction.v1/scratch/output/evidence/'
b=json.load(open(S+'f04-before.json')); a=json.load(open(S+'f04-after.json'))
bc={c['case']:c for c in b['cases']}; ac={c['case']:c for c in a['cases']}
def brief(c):
    if c is None: return 'n/a'
    out=[]
    if 'schemaValid' in c: out.append('schema='+str(c['schemaValid']))
    m=c.get('membership')
    if m:
        if m['outcome']=='RETURNED':
            kinds=sorted(set(r['membership'] for r in m['rows']))
            out.append('membership=RETURNED'+str(kinds))
        else: out.append('membership=REFUSED:'+m['message'].split(':')[0])
    s=c.get('scope')
    if s: out.append('scope='+(s['outcome']+str(s.get('workspaceRoots','')) if s['outcome']=='RETURNED' else 'REFUSED'))
    if 'caps' in c: out.append('caps='+c['caps']['outcome'])
    if 'outcome' in c: out.append('outcome='+c['outcome'])
    return ' | '.join(out)
for k in [c['case'] for c in b['cases']]:
    print('==',k)
    print('   BEFORE:',brief(bc.get(k)))
    print('   AFTER :',brief(ac.get(k)))
PYEOF
